"""Private document objects. Keys are generated by the server, never filenames."""
import hashlib
import os
import re
from pathlib import Path
from typing import Protocol
from app.core.config import settings


class DocumentStore(Protocol):
    def put(self, key: str, content: bytes) -> None: ...
    def get(self, key: str) -> bytes: ...
    def delete(self, key: str) -> None: ...


def validate_key(key):
    if not re.fullmatch(r"tenant-[a-f0-9]{32}/[a-f0-9]{32}\.pdf", key):
        raise ValueError("Invalid private object key.")
    return key


def object_key(tenant_id, job_id):
    return f"tenant-{hashlib.sha256(tenant_id.encode()).hexdigest()[:32]}/{job_id}.pdf"


class LocalDocuments:
    def __init__(self, root):
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)

    def path(self, key):
        target = (self.root/validate_key(key)).resolve()
        if not target.is_relative_to(self.root): raise ValueError("Invalid private object path.")
        return target

    def put(self, key, content):
        path = self.path(key)
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, "wb") as output: output.write(content)

    def get(self, key): return self.path(key).read_bytes()
    def delete(self, key): self.path(key).unlink(missing_ok=True)


class S3Documents:
    def __init__(self, client=None):
        import boto3
        self.client = client or boto3.client("s3", endpoint_url=settings.s3_endpoint_url or None, region_name=settings.s3_region)
        self.bucket = settings.s3_bucket
        if not self.bucket: raise ValueError("S3_BUCKET is required.")

    def put(self, key, content):
        self.client.put_object(Bucket=self.bucket, Key=validate_key(key), Body=content, ContentType="application/pdf", ServerSideEncryption="AES256", ChecksumSHA256=__import__("base64").b64encode(hashlib.sha256(content).digest()).decode())

    def get(self, key):
        response = self.client.get_object(Bucket=self.bucket, Key=validate_key(key))
        body = response["Body"]
        try:
            content = body.read(settings.max_upload_bytes+1)
            if len(content) > settings.max_upload_bytes: raise ValueError("Stored document exceeds the configured limit.")
            return content
        finally: body.close()

    def delete(self, key): self.client.delete_object(Bucket=self.bucket, Key=validate_key(key))


def document_store(root):
    if settings.document_store == "s3": return S3Documents()
    if settings.document_store != "local": raise ValueError("Unknown document store.")
    return LocalDocuments(Path(root)/"documents")
